// Interface language: French (the source texts) or English.
// The screens are written in French; this layer translates what they render, on the fly, and never touches
// what people wrote: conversations, page content, articles, before/after cards, form values.
// Untranslated interface texts are collected in window.claudepressMissing() to complete the list.
const KEY = 'claudepress-lang';

export function currentLang() {
  try { const s = localStorage.getItem(KEY); if (s === 'fr' || s === 'en') return s; } catch {}
  return (navigator.language || 'fr').toLowerCase().startsWith('fr') ? 'fr' : 'en';
}

export async function setLang(lang, { save = true } = {}) {
  try { localStorage.setItem(KEY, lang); } catch {}
  if (save) await fetch('/api/me/lang', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ lang }) }).catch(() => {});
  location.reload();
}

const lang = currentLang();
document.documentElement.lang = lang;

