// ---- translating what the screens render

const SKIP = '.msg, .ba del, .ba ins, .ba li, .blocks, .post-title, .serp, .cover img, .where, .row .t strong, [contenteditable], code, pre, .no-translate';
const missing = new Set();
const ENGLISH = new Set(Object.values(EN));

/** The English of an extension's screens (server/extension.ts), added to the app's. */
export function addEnglish(entries) {
  Object.assign(EN, entries);
  for (const v of Object.values(entries)) if (typeof v === 'string') ENGLISH.add(v);
}
window.claudepressMissing = () => [...missing].sort();

const relative = s => s.replace(/il y a (\d+) min/g, '$1 min ago').replace(/il y a (\d+) h/g, '$1 h ago').replace(/à l’instant/g, 'just now');

/** One piece of interface text: exact text, then patterns. */
function one(t) {
  if (t in EN) return EN[t];
  if (ENGLISH.has(t)) return t;
  for (const [re, to] of PATTERNS) if (re.test(t)) return relative(t.replace(re, to));
  return null;
}

function tr(text) {
  const t = text.trim().replace(/\s+/g, ' ');
  if (!t || !/[a-zàâçéèêëîïôûùüÿœ]/i.test(t)) return null;
  let out = one(t);
  // lines made of pieces ("Modification · Claire · il y a 5 h", "Peut publier : …"): piece by piece
  if (out == null && (t.includes(' · ') || / : /.test(t))) {
    const sep = t.includes(' · ') ? ' · ' : ' : ';
    const parts = t.split(sep).map(p => one(p) ?? relative(p));
    if (parts.join(sep) !== t) out = parts.join(sep);
  }
  if (out == null && /il y a \d+ (min|h)|à l’instant/.test(t)) out = relative(t);
  if (out != null) return out === t ? null : text.replace(text.trim(), out);
  if (/[àâçéèêîôûœ’]|\b(le|la|les|des|du|une?|vos|votre|pour|avec|sur|dans|est|pas|sans)\b/i.test(t)) missing.add(t);
  return null;
}

const done = new WeakSet();
function translateNode(root) {
  if (root.nodeType === 3) {
    const p = root.parentElement;
    // a textarea's text is what people typed; in before/after cards only the labels are interface
    if (!p || done.has(root) || p.closest(SKIP) || p.tagName === 'TEXTAREA' || p.matches('.ba > div')) return;
    const out = tr(root.nodeValue);
    done.add(root);
    if (out != null && out !== root.nodeValue) root.nodeValue = out;
    return;
  }
  if (root.nodeType !== 1 || root.closest?.(SKIP)) return;
  for (const attr of ['placeholder', 'title', 'aria-label']) {
    const v = root.getAttribute?.(attr);
    if (v) { const out = tr(v); if (out != null && out !== v) root.setAttribute(attr, out); }   // same text: no write, or the observer would loop
  }
  for (const child of root.childNodes) translateNode(child);
}

function addSwitch() {
  for (const host of document.querySelectorAll('header.top, .login')) {
    if (host.querySelector(':scope > .lang-switch')) continue;
    const b = document.createElement('button');
    b.className = 'btn ghost small lang-switch no-translate';
    b.type = 'button';
    b.title = lang === 'fr' ? 'Switch to English' : 'Passer en français';
    b.textContent = lang === 'fr' ? 'EN' : 'FR';
    b.addEventListener('click', () => setLang(lang === 'fr' ? 'en' : 'fr'));
    if (host.matches('header.top')) host.insertBefore(b, host.querySelector('#bell') || null);
    else host.appendChild(b);
  }
}

if (lang === 'en') {
  const confirm0 = window.confirm.bind(window);
  window.confirm = msg => confirm0(tr(String(msg)) ?? msg);
}

new MutationObserver(muts => {
  if (lang === 'en') for (const m of muts) {
    if (m.type === 'characterData') { done.delete(m.target); translateNode(m.target); }
    for (const n of m.addedNodes) translateNode(n);
    if (m.type === 'attributes') translateNode(m.target);
  }
  addSwitch();
}).observe(document.documentElement, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ['placeholder', 'title', 'aria-label'] });

// once signed in, the account's language wins (it follows the person from device to device)
fetch('/api/me').then(r => r.ok ? r.json() : null).then(me => {
  const saved = me?.user?.lang;
  if (saved && saved !== lang) setLang(saved, { save: false });
}).catch(() => {});
